import 'dart:io';

import 'package:ffmpeg_kit_flutter_new_audio/ffmpeg_kit.dart';
import 'package:ffmpeg_kit_flutter_new_audio/ffprobe_kit.dart';
import 'package:ffmpeg_kit_flutter_new_audio/return_code.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:tube_downloader/core/download_core/data/muxer/ffmpeg_kit_muxer.dart';
import 'package:tube_downloader/core/download_core/domain/repos/media_muxer.dart';

/// The real FFmpeg plugin inside this app (macOS / iOS / Android device):
/// fixtures are generated by FFmpeg itself (test pattern + tone), then merged
/// and converted by the app's muxer and checked with FFprobe.
///   flutter test integration_test/ffmpeg_muxer_test.dart -d macos --flavor development
void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  late Directory dir;
  setUpAll(() async {
    // The process temp dir always exists (the app's Caches folder may not yet).
    dir = await Directory.systemTemp.createTemp('muxer_it');
  });
  tearDownAll(() => dir.delete(recursive: true));

  Future<void> ffmpeg(List<String> args) async {
    final session = await FFmpegKit.executeWithArguments(args);
    final rc = await session.getReturnCode();
    expect(
      ReturnCode.isSuccess(rc),
      isTrue,
      reason: (await session.getAllLogsAsString())
          ?.split('\n')
          .reversed
          .take(5)
          .join('\n'),
    );
  }

  Future<List<String>> probe(String path) async {
    final info = (await FFprobeKit.getMediaInformation(path))
        .getMediaInformation();
    expect(info, isNotNull, reason: 'ffprobe could not read $path');
    return info!
        .getStreams()
        .map((s) => '${s.getType()}:${s.getCodec()}')
        .toList();
  }

  testWidgets('merge (copy) and MP3 conversion through FfmpegKitMuxer', (
    tester,
  ) async {
    final video = '${dir.path}/video.mp4';
    final audio = '${dir.path}/audio.m4a';
    await ffmpeg([
      '-y',
      '-f',
      'lavfi',
      '-i',
      'testsrc=duration=3:size=320x240:rate=30',
      '-c:v',
      'mpeg4',
      '-pix_fmt',
      'yuv420p',
      video,
    ]);
    await ffmpeg([
      '-y',
      '-f',
      'lavfi',
      '-i',
      'sine=frequency=440:duration=3',
      '-c:a',
      'aac',
      audio,
    ]);

    final muxer = FfmpegKitMuxer();
    final merged = '${dir.path}/out.mp4';
    final mergeUpdates = await muxer
        .merge(
          jobId: 'm',
          videoPath: video,
          audioPath: audio,
          outputPath: merged,
          duration: const Duration(seconds: 3),
        )
        .toList();
    expect(mergeUpdates.last, const MuxUpdate.done());
    expect(await probe(merged), containsAll(['video:mpeg4', 'audio:aac']));

    final mp3 = '${dir.path}/out.mp3';
    final mp3Updates = await muxer
        .toMp3(jobId: 'a', audioPath: audio, outputPath: mp3, kbps: 192)
        .toList();
    expect(mp3Updates.last, const MuxUpdate.done());
    expect(await probe(mp3), ['audio:mp3']);
  });

  testWidgets('a broken input fails as ffmpegFailed, not an exception', (
    tester,
  ) async {
    final bogus = '${dir.path}/bogus.mp4';
    await File(bogus).writeAsString('not a video');
    final updates = await FfmpegKitMuxer()
        .merge(
          jobId: 'x',
          videoPath: bogus,
          audioPath: bogus,
          outputPath: '${dir.path}/never.mp4',
        )
        .toList();
    expect(updates.last, isA<MuxFailed>());
  });
}
